<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest\UserPersonalApiKeyAllowController;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest\UserPersonalApiKeyListController;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest\UserPersonalApiKeyCreateController;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest\UserPersonalApiKeyRetrieveController;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest\UserPersonalApiKeyUpdateController;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest\UserPersonalApiKeyDeleteController;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest\UserPersonalApiKeyRevokeController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Service\Visibility\UserPersonalApiKeyRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Policy\Filter\OnlySelfAccesibles;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driven\UserPersonalApiKeyReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driven\UserPersonalApiKeyWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Gateway\UserPersonalApiKeyReadGateway;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Gateway\UserPersonalApiKeyWriteGateway;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Policy\Allow\IsSelfUserAllow;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Update\UserPersonalApiKeyUpdateAllowDecision;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Retrieve\UserPersonalApiKeyRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Delete\UserPersonalApiKeyDeleteAllowDecision;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Revoke\UserPersonalApiKeyRevokeAllowDecision;

class UserPersonalApiKeyPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[UserPersonalApiKeyReadGateway::class] = \DI\autowire(UserPersonalApiKeyReadRepositoryAdapter::class);
        $def[UserPersonalApiKeyWriteGateway::class] = \DI\autowire(UserPersonalApiKeyWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/me/api-keys', [$this, 'setRoutesForUserPersonalApiKey']);
        $collector->group('/api/me/acl/access/me/api-keys', [$this, 'setRoutesForUserPersonalApiKeyAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(UserPersonalApiKeyRestrictFilterToVisibility::class, OnlySelfAccesibles::class);
        $listener->registerListener(UserPersonalApiKeyRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(UserPersonalApiKeyUpdateAllowDecision::class, IsSelfUserAllow::class, 'checkUpdate');
        $listener->registerListener(UserPersonalApiKeyRetrieveAllowDecision::class, IsSelfUserAllow::class, 'checkRetrieve');
        $listener->registerListener(UserPersonalApiKeyDeleteAllowDecision::class, IsSelfUserAllow::class, 'checkDelete');
        $listener->registerListener(UserPersonalApiKeyRevokeAllowDecision::class, IsSelfUserAllow::class, 'checkRevoke');
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("user-personal-api-key", "list", "READ");
            $handler->registerResourceAction("user-personal-api-key", "create", "WRITE");
            $handler->registerResourceAction("user-personal-api-key", "retrieve", "READ");
            $handler->registerResourceAction("user-personal-api-key", "update", "WRITE");
            $handler->registerResourceAction("user-personal-api-key", "delete", "WRITE");
            $handler->registerResourceAction("user-personal-api-key", "revoke", "WRITE");

            $handler->registerResourceAttribute("user-personal-api-key", "user", "MANAGE");
            $handler->registerResourceAttribute("user-personal-api-key", "name", "MANAGE");
            $handler->registerResourceAttribute("user-personal-api-key", "keyHash", "MANAGE");
            $handler->registerResourceAttribute("user-personal-api-key", "scopes", "MANAGE");
            $handler->registerResourceAttribute("user-personal-api-key", "lastUsedAt", "MANAGE");
            $handler->registerResourceAttribute("user-personal-api-key", "expiresAt", "MANAGE");
            $handler->registerResourceAttribute("user-personal-api-key", "createdAt", "MANAGE");
            $handler->registerResourceAttribute("user-personal-api-key", "enabled", "MANAGE");
            $handler->registerResourceAttribute("user-personal-api-key", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForUserPersonalApiKeyAcl(RouteCollectorProxy $userPersonalApiKeyGroup): void
    {
        $userPersonalApiKeyGroup->get('', [UserPersonalApiKeyAllowController::class, 'genericAllow']);
        $userPersonalApiKeyGroup->get('/{uid}', [UserPersonalApiKeyAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForUserPersonalApiKey(RouteCollectorProxy $userPersonalApiKeyGroup): void
    {
        $userPersonalApiKeyGroup->get('', [UserPersonalApiKeyListController::class, 'list']);
        $userPersonalApiKeyGroup->post('', [UserPersonalApiKeyCreateController::class, 'create']);
        $userPersonalApiKeyGroup->get('/{uid}', [UserPersonalApiKeyRetrieveController::class, 'retrieve']);
        $userPersonalApiKeyGroup->put('/{uid}', [UserPersonalApiKeyUpdateController::class, 'update']);
        $userPersonalApiKeyGroup->delete('/{uid}', [UserPersonalApiKeyDeleteController::class, 'delete']);
        $userPersonalApiKeyGroup->delete('', [UserPersonalApiKeyDeleteController::class, 'deleteAllForQuery']);
        $userPersonalApiKeyGroup->get('/~/delete-status/{uid}', [UserPersonalApiKeyDeleteController::class, 'checkDeleteAllForQueryStatus']);
        $userPersonalApiKeyGroup->patch('/~/revoke', [UserPersonalApiKeyRevokeController::class, 'revokeAllForQuery']);
        $userPersonalApiKeyGroup->patch('/{uid}/revoke', [UserPersonalApiKeyRevokeController::class, 'revoke']);
        $userPersonalApiKeyGroup->get('/~/revoke-status/{uid}', [UserPersonalApiKeyRevokeController::class, 'checkRevokeAllForQueryStatus']);
    }
}
